import{z as s,x as B,o as r,c as p,q as o,j as t,D as E,d as e,s as i,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"LoRA 合并与冲突","description":"","frontmatter":{"title":"LoRA 合并与冲突","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lora-merge-conflict.md","filePath":"llm/lora-merge-conflict.md","lastUpdated":1791063341000}'),m={name:"llm/lora-merge-conflict.md"};function d(_,a,u,C,h,D){const A=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="lora-合并与冲突" tabindex="-1">LoRA 合并与冲突 <a class="header-anchor" href="#lora-合并与冲突" aria-label="Permalink to &quot;LoRA 合并与冲突&quot;">​</a></h1><div class="epigraph"><p>两个适配器相加，秩至多相加，任务方向却可能互相抵消；线性合并是产品操作，不是 LoRA 原论文保证的交换律。</p><footer>—— 承接 Hu 等 LoRA（2021）的单任务合并；冲突侧对照 Yadav 等 TIES-Merging（NeurIPS 2023）、Yu 等 DARE（ICML 2024）</footer></div><p><a href="/llm/p-tuning-v2">P-tuning v2</a> 用切换前缀避免把任务写进 \\(W\\)。LoRA 服务常走另一条：把 \\(\\Delta W_i=B_iA_i\\) 加进同一份 \\(W_0\\)，希望同时会编程又会客服。<a href="/llm/lora">LoRA 课</a>已警告多适配器相加无通用保证。本课把缺口展开：何时加法近似成立、符号冲突怎么消、以及为何<a href="/llm/rslora">rsLoRA</a> 缩放不同的适配器不能裸加。下一课再谈 MoE 上插在哪里。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单任务部署：算 \\(W=W_0+\\gamma BA\\)，推理与稠密相同。多任务想免去切换 GEMM，就写</p> \\[W=W_0+\\sum_i \\lambda_i\\gamma_i B_iA_i. \\]<p>若各 \\(\\Delta W_i\\) 作用在近似正交的子空间、且 \\(\\lambda_i\\) 小，表现像「技能并集」。若两个任务改同一批通道而符号相反（一个要更冗长、一个要更短），加法变成抵消或随机胜出。TIES-Merging（Yadav 等人，NeurIPS 2023）指出模型合并里的三类干扰：符号不一致、小幅度噪声、密度过高。LoRA 合并是模型合并的低秩特例。</p><p><span class="marginnote">常见误区：初学者容易以为合并 LoRA 像合并文件夹，两个适配器各管各的。实际两份 \\(\\Delta W\\) 是写进同一批权重通道的加法：重叠的地方直接做算术，一个要输出更长、一个要输出更短，加完可能两边能力都打折。</span></p><p>不同 \\(r\\)、不同 \\(\\gamma\\)（含 rsLoRA 与否）、不同插入位置，连矩阵形状都不共享，不能逐元素加。</p><p><span class="marginnote">数字实例：两个 \\(r=8\\) 的适配器相加，列空间之和的秩至多 \\(8+8=16\\)；若重叠方向不少且部分反向，有效秩会明显低于 16，任务能力在求和中互相吃掉——所以「秩够」从来不代表「合并无害」。</span></p><h3 id="合并不可逆-除非另存因子" tabindex="-1">合并不可逆，除非另存因子 <a class="header-anchor" href="#合并不可逆-除非另存因子" aria-label="Permalink to &quot;合并不可逆，除非另存因子&quot;">​</a></h3><p>加进 \\(W_0\\) 后丢掉 \\(A,B\\)，无法拆回任务。要可逆，必须保存因子或保存合并前的 \\(W_0\\)。ReLoRA 训练期合并与此处产品合并是同一加法，目的相反：前者堆秩，后者堆任务。</p><p><span class="marginnote">Huang 等人的 LoRAHub 用少量样本学组合系数 \\(\\lambda_i\\)。系数可学，说明裸 \\(\\lambda_i=1\\) 通常不是最优。DARE（Yu 等，ICML 2024）则先随机丢差分再缩放，减轻同源模型合并的干扰。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先对齐：同一基座检查点、同一插入模块集合、同一<a href="/llm/chat-template">模板</a>。然后选策略：（1）不合并，运行时切适配器；（2）加权和，扫 \\(\\lambda\\)；（3）TIES 式：修剪小幅度、对冲突符号选举、再平均；（4）在验证集上学 \\(\\lambda\\)（LoRAHub 类）。评测必须含单任务回归：合并后任务 A 不得默默掉到不可用。</p><p>缩放：先把每个适配器的 \\(\\gamma BA\\) 物化到同一表示再加。一个用 \\(\\alpha/r\\)、一个用 \\(\\alpha/\\sqrt{r}\\)，直接加 \\(B,A\\) 是 bug。</p>',16)),(r(),t(n,null,{default:E(()=>[i(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A1%5B%22%E9%80%82%E9%85%8D%E5%99%A8%20A%22%5D%20--%3E%20C%5B%22%E5%AF%B9%E9%BD%90%E5%9F%BA%E5%BA%A7%E4%B8%8E%20%CE%B3%22%5D%0A%20%20A2%5B%22%E9%80%82%E9%85%8D%E5%99%A8%20B%22%5D%20--%3E%20C%0A%20%20C%20--%3E%20M%5B%22%E5%8A%A0%E6%9D%83%20%2F%20TIES%20%2F%20%E5%AD%A6%20%CE%BB%22%5D%0A%20%20M%20--%3E%20V%5B%22%E5%8D%95%E4%BB%BB%E5%8A%A1%20%2B%20%E8%81%94%E5%90%88%E9%AA%8C%E8%AF%81%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,[e("数据侧：两个 LoRA 若 SFT 谱系不同（FLAN 对 ShareGPT），合并等于混条件分布，"),l("a",{href:"/llm/response-only-loss"},"仅回复"),e("学到的结束符习惯会打架。优先在数据配比上混训一个适配器，而不是训两个再加。")],-1)),a[4]||(a[4]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=l("p",null,"\\(\\Delta W_1+\\Delta W_2\\) 的列空间是两者列空间的和，秩 \\(\\le r_1+r_2\\)。干扰发生在重叠的奇异方向上：同向则加强（可能过饱和），反向则相消。TIES 的符号选举假设「多数任务同意的符号是真信号」——对同源、同目标的检查点较真，对「安全 LoRA + 越狱 LoRA」荒谬。DARE 假设差分里有大量冗余：随机丢弃仍能保留能力，再放大补偿。LoRA 很稀疏时 DARE 可能把仅有的 \\(r\\) 个方向丢掉。",-1)),(r(),t(n,null,{default:E(()=>[i(A,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22%E5%90%88%E5%B9%B6%20%CE%94W1%20%E5%8A%A0%20%CE%94W2%22%5D%20--%3E%20Q%7B%22%E9%87%8D%E5%8F%A0%E5%A5%87%E5%BC%82%E6%96%B9%E5%90%91%E4%B8%8A%E7%9A%84%E7%AC%A6%E5%8F%B7%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%8C%E5%90%91%22%7C%20R1%5B%22%E5%8A%A0%E5%BC%BA%EF%BC%8C%E5%8F%AF%E8%83%BD%E8%BF%87%E9%A5%B1%E5%92%8C%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8F%8D%E5%90%91%22%7C%20R2%5B%22%E7%9B%B8%E6%B6%88%EF%BC%9A%E5%A6%82%E4%B8%80%E4%B8%AA%E8%A6%81%E5%86%97%E9%95%BF%E4%B8%80%E4%B8%AA%E8%A6%81%E7%AE%80%E7%9F%AD%22%5D%0A%20%20Q%20--%3E%7C%22%E8%BF%91%E4%BC%BC%E6%AD%A3%E4%BA%A4%22%7C%20R3%5B%22%E8%BF%91%E4%BC%BC%E6%8A%80%E8%83%BD%E5%B9%B6%E9%9B%86%EF%BC%8C%E7%A7%A9%E8%87%B3%E5%A4%9A%20r1%20%E5%8A%A0%20r2%22%5D%0A%20%20R2%20--%3E%20FIX%5B%22%E9%9C%80%E7%AC%A6%E5%8F%B7%E9%80%89%E4%B8%BE%E8%A3%81%E5%86%B3%E5%90%8E%E5%86%8D%E6%B1%82%E5%92%8C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">术语翻译：「符号选举」是 TIES-Merging 的操作——把重叠通道上各家更新的正负号拿出来投票，保留多数派符号、只平均属于多数派的更新，少数派直接丢弃。先把「吵架的方向」裁决掉，剩下的再安心做加法。</span></p><p>服务期不合并、只切 \\(A,B\\)，没有加法冲突，但有加载延迟与额外 GEMM。Punica 一类内核优化的是切适配器，不是让加法变合法。</p><p><span class="marginnote">BitFit 的 Δb 相加同样会冲突，只是诊断更容易：看通道符号。前缀 KV 应切换，平均前缀常得到无意义的键。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有通用的「把商店里的 LoRA 线性融合」。安全与能力适配器尤其不要裸加。同一数据不同随机种子的soup（模型汤）比异质任务相加更安全。合并后要做源域回归：加法可能意外放大遗忘。MoE 上还有专家路由与 LoRA 的位置冲突，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单任务合并 \\(W_0+\\gamma BA\\) 是合法部署；多任务求和无交换律保证。</li><li>先对齐基座、插入位置与缩放，再谈 \\(\\lambda\\) 或 TIES。</li><li>符号冲突会相消；异质谱系优先混训而不是事后加。</li><li>可逆性要求保留因子或原 \\(W_0\\)。</li><li>运行时切换回避加法，付出额外 GEMM。</li><li>出处：Hu 等，LoRA，2021；Yadav 等，TIES-Merging，NeurIPS 2023；Yu 等，DARE，ICML 2024。</li></ul>',7))])}const f=s(m,[["render",d]]);export{c as __pageData,f as default};
